DEFAULT_POOL_TIE_BREAKERS = (
    (1, "MATCHES_WON"),
    (2, "RACK_DIFFERENCE"),
    (3, "RACKS_WON"),
    (4, "HEAD_TO_HEAD"),
)


def seed_default_pool_tie_breakers(apps, schema_editor):
    """Give every existing competition the approved complete safe default."""
    PoolCompetition = apps.get_model("pool", "PoolCompetition")
    PoolCompetitionTieBreaker = apps.get_model("pool", "PoolCompetitionTieBreaker")

    rows = []
    for competition_id in PoolCompetition.objects.values_list("pk", flat=True):
        if PoolCompetitionTieBreaker.objects.filter(
            competition_id=competition_id
        ).exists():
            continue
        rows.extend(
            PoolCompetitionTieBreaker(
                competition_id=competition_id,
                order=order,
                criterion=criterion,
            )
            for order, criterion in DEFAULT_POOL_TIE_BREAKERS
        )
    if rows:
        PoolCompetitionTieBreaker.objects.bulk_create(rows)


